          state <= 3'b011;
        end
        3'b011: begin
          q_out <= 4'b0100;
          q_bar_out <= 4'b1011;
          state <= 3'b100;
        end
        3'b100: begin
          q_out <= 4'b0101;
          q_bar_out <= 4'b1010;
          state <= 3'b101;
        end
        3'b101: begin
          q_out <= 4'b0110;
          q_bar_out <= 4'b1001;
          state <= 3'b110;
        end
        3'b110: begin
