module top_module(A1, A2, CE1, CE2, WEB1, WEB2, OEB1, OEB2, CSB1, CSB2, I1, I2, O1, O2);parameter numAddr = 7;
  parameter wordLength = 8;
  parameter numWords = 128;

  input [numAddr-1:0] A1;
  input [numAddr-1:0] A2;
  input CE1;
  input CE2;
  input WEB1;
  input WEB2;
  input OEB1;
  input OEB2;
  input CSB1;
  input CSB2;
  input [wordLength-1:0] I1;
  input [wordLength-1:0] I2;
  output [wordLength-1:0] O1;
  output [wordLength-1:0] O2;

  reg [wordLength-1:0] memory [numWords-1:0];

  reg [numAddr-1:0] addr1;
  reg [numAddr-1:0] addr2;
  reg [wordLength-1:0] data1;
  reg [wordLength-1:0] data2;
  reg [wordLength-1:0] data_out1;
  reg [wordLength-1:0] data_out2;

  assign O1 = (OEB1) ? data_out1 : 8'bzzzzzzzz;
  assign O2 = (OEB2) ? data_out2 : 8'bzzzzzzzz;

  always @(posedge CSB1 or negedge CSB1 or posedge CSB2 or negedge CSB2) begin
    if (!CSB1) begin
      addr1 <= A1;
      if (WEB1) memory[A1] <= I1;
      data_out1 <= memory[A1];
    end
    if (!CSB2) begin
      addr2 <= A2;
      if (WEB2) memory[A2] <= I2;
      data_out2 <= memory[A2];
    end
  end

endmodule

