module top_module(
    input wire DCLK_IN,
    input wire [15:0] DI_IN,
    input wire DWE_IN,
    input wire DEN_IN,
    input wire VP_IN,
    input wire VN_IN,
    output reg DRDY_OUT,
    output reg [15:0] DO_OUT,
    input wire [6:0] DADDR_IN
    );reg [15:0] temperature;
    reg [15:0] data_reg;
    reg [1:0] state;
    reg [3:0] counter;

    always @(posedge DCLK_IN) begin
        if (DEN_IN) begin
            case (state)
                2'b00: begin
                    data_reg <= DI_IN;
                    state <= 2'b01;
                    counter <= 4'd0;
                end
                2'b01: begin
                    counter <= counter + 1;
                    if (counter == 4'd7) begin
                        state <= 2'b10;
                        counter <= 4'd0;
                    end
                end
                2'b10: begin
                    temperature <= {data_reg[11:0], DI_IN[3:0]};
                    state <= 2'b00;
                    DRDY_OUT <= 1'b1;
                end
            endcase
        end else if (DWE_IN) begin
            case (DADDR_IN)
                7'h00: begin
                    DO_OUT <= temperature;
                    DRDY_OUT <= 1'b0;
                end
                default: begin
                    DO_OUT <= 16'h0000;
                    DRDY_OUT <= 1'b0;
                end
            endcase
        end
    end

endmodule

