module top_module(
  input clk_in,
  input reset,
  input enable,
  output clk_out
);parameter f_nom = 50; // nominal frequency (MHz)
parameter d_f = 1; // frequency deviation (MHz)
parameter mod_rate = 5; // modulation rate (MHz)
parameter polynomial = 16'hB400; // polynomial sequence

reg [15:0] poly_reg;
reg [31:0] counter;
reg clk_out_reg;

assign clk_out = clk_out_reg;

always @(posedge clk_in or posedge reset) begin
  if (reset) begin
    poly_reg <= 16'h0001;
    counter <= 0;
    clk_out_reg <= 1'b0;
  end else begin
    if (enable) begin
      if (counter < (f_nom / mod_rate)) begin
        counter <= counter + 1;
      end else begin
        counter <= 0;
        poly_reg <= {poly_reg[14:0], poly_reg[15] ^ poly_reg[0]};
      end
      clk_out_reg <= clk_in ^ poly_reg[0];
    end else begin
      clk_out_reg <= clk_in;
    end
  end
end

endmodule

