    input fifo_wr,
    output fifo_FF,
    output reg [7:0] r_dat, // Changed from wire to reg
    output wfifo_empty,
    output [5:0] wfifo_used
);reg [7:0] fifo [0:63]; // 64-word FIFO
    reg [5:0] fifo_head = 0;
    reg [5:0] fifo_tail = 0;
    reg [5:0] fifo_count = 0;

    assign wfifo_used = fifo_count;
    assign fifo_FF = (fifo_count == 64);
    assign wfifo_empty = (fifo_count == 0);

    always @(posedge clk) begin
        if (fifo_wr && !fifo_FF) begin // Added condition to check for full FIFO
            fifo[fifo_tail] <= fifo_wdata;
            fifo_tail <= (fifo_tail == 63) ? 0 : fifo_tail + 1;
            fifo_count <= fifo_count + 1;
        end
        if (fifo_count > 0) begin
            r_dat <= fifo[fifo_head];
            fifo_head <= (fifo_head == 63) ? 0 : fifo_head + 1;
            fifo_count <= fifo_count - 1;
        end
    end

