module piso_shift_register
(
  input rst_n,
  input clk,
  input load,
  input [23:0] parallel_in,

  output reg serial_out,
  output reg [23:0] out
);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) 
	begin
      out <= 24'd0;
      serial_out <= 1'b0;
    end 
	else if (load) 
	begin
      out <= parallel_in;
    end 
	else 
	begin
      serial_out <= out[0];
      out <= out >> 1;
    end
  end

endmodule

