module top_module(
	 input G,
    input [1:0] C,
    input [3:0] X,
    output Y
    );wire [1:0] sel;
	wire x0;
	wire x1;
	wire x2;
	wire x3;
	reg out;

	assign sel = {C[1], C[0]};
	assign x0 = X[0];
	assign x1 = X[1];
	assign x2 = X[2];
	assign x3 = X[3];

	assign Y = ~out;

	always@(G or sel or x0 or x1 or x2 or x3)
		begin
			if (G == 1'b0)
				begin
					if (sel == 2'b00 && x0 == 1'b1)
						begin 
							out = 1'b0;
						end
					else if (sel == 2'b01 && x1 == 1'b1)
						begin 
							out = 1'b0;
						end
					else if (sel == 2'b10 && x2 == 1'b1)
						begin
							out = 1'b0;
						end
					else if (sel == 2'b11 && x3 == 1'b1)
						begin
							out = 1'b0;
						end
					else
						begin
							out = 1'b1;
						end
				end
		end


endmodule

