description:
Design a 4-bit unsigned multiplication module that computes the product of two 4-bit inputs, M and N, producing an 8-bit output P. The design utilizes an array-based multiplication approach, where it generates partial products based on the bit-wise multiplication of M and N and accumulates these values to form the final product. The outputs are structured to represent the 8-bit result of the multiplication operation.
module top_module(
    input [3:0] M,
    input [3:0] N,
    output reg [7:0] P
);

code:
module top_module(
    input [3:0] M,
    input [3:0] N,
    output reg [7:0] P
);reg [7:0] partial_products [0:3];

integer i, j;

always @(*) begin
    // Initialize partial_products to zero at the beginning of the calculation
    for (i = 0; i < 4; i = i + 1) begin
        partial_products[i] = 8'b0;
    end

    // Calculate the partial products
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            partial_products[i + j] = partial_products[i + j] + (M[i] * N[j]);
        end
    end

    // Assign the result to P by combining the partial products
    P = {partial_products[3], partial_products[2], partial_products[1], partial_products[0]};
end

endmodule

module top_module(
		clk,
		rst,

		is_sticky,

		delay_valid,
		delay_cycles,

		pred_valid,
		pred_match,
		pred_index,

		act_input,
		act_output,
		act_index
	);input clk;
	input rst;

	input is_sticky;

	input pred_valid;
	input pred_match;
	input [15:0] pred_index;

	input delay_valid;
	input [3:0] delay_cycles;

	input act_input;
	output reg act_output;
	output reg [15:0] act_index;

	reg activated;

	reg [3:0] delay_cycles_reg;

	reg [2+15:0] delay_shift;

	always @(posedge clk ) begin

		if (delay_valid==1) delay_cycles_reg <= delay_cycles;

		if (rst) begin
			act_output <= 0;					
			activated <= 0;
		end			
		else 
		begin 

			delay_shift <= {delay_shift[14:2],act_input,2'b00};

			activated <= (delay_cycles_reg>1) ? delay_shift[delay_cycles_reg] : act_input;

			if (pred_valid) begin

				if ((delay_cycles_reg==0 && act_input==1) || (delay_cycles_reg!=0 && activated==1) && pred_match==1) begin			
					act_output <= pred_match;	

					if (act_output==0) act_index <= pred_index;
				end
				else begin
					if (is_sticky) begin
						act_output <= act_output;
					end else begin
						act_output <= 0;
					end
				end
			end
			else begin
				if (is_sticky) begin
					act_output <= act_output;
				end else begin
					act_output <= 0;
				end
			end

		end
	end

endmodule

