description:
Design a 4-to-1 multiplexer that selects one of four 1-bit input signals based on a 2-bit selection input. The output will be determined by the value of the selection input (sel); when sel is 00, output data_in[0]; when sel is 01, output data_in[1]; when sel is 10, output data_in[2]; and when sel is 11, output data_in[3].
module top_module(
    input  [3:0] data_in,
    input  [1:0] sel,
    output reg     data_out
);

code:
module top_module(
    input  [3:0] data_in,
    input  [1:0] sel,
    output reg     data_out
);wire [3:0] sel_inv;
    assign sel_inv = ~sel;

    always @ (*) begin
        if (sel == 2'b00) begin
            data_out = data_in[0];
        end else if (sel == 2'b01) begin
            data_out = data_in[1];
        end else if (sel == 2'b10) begin
            data_out = data_in[2];
        end else if (sel == 2'b11) begin
            data_out = data_in[3];
        end
    end

endmodule

module top_module( g, p, g_prec, g_out );input g, p;
  input [1:0] g_prec;
  output g_out;
  wire n2;

  // AOI21 equivalent using standard gates
  wire a_input = g;
  wire b_input = p;
  wire c_input = g_prec[1];

  assign n2 = ~( (b_input & c_input) | a_input );

  // Inverter gate using standard gate
  assign g_out = ~n2;

endmodule

