module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter W=2'b00, X=2'b01, Y=2'b10, Z=2'b11;

    always_comb begin
		case (state)
			W: next_state = in ? Y : X;
			X: next_state = in ? Z : Y;
			Y: next_state = in ? W : Z;
			Z: next_state = in ? X : W;
		endcase
    end

    assign out = (state == W) || (state == Y);

endmodule

