module top_module(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);wire [3:0] sum;
wire c1, c2, c3;

assign sum = A + B + Cin;
assign Cout = c3;

assign c1 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
assign c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);
assign c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2) | (A[3] & B[3]) | (A[3] & c2) | (B[3] & c2);

assign S = sum;

endmodule

module top_module(
    input clk,
    input shiftnld,
    input ldsrc,
    input rst,
    output crcerror,
    output [15:0] regout
);reg [15:0] shift_reg;
reg [15:0] crc_reg;
reg [3:0] crc_count;
wire [15:0] crc_expected;

assign crc_expected = 16'h800D;

assign crcerror = (crc_reg != crc_expected);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        shift_reg <= 16'h0000;
        crc_reg <= 16'h0000;
        crc_count <= 4'h0;
    end else if (ldsrc) begin
        shift_reg <= 16'h0000;
        crc_reg <= 16'h0000;
        crc_count <= 4'h0;
    end else if (shiftnld) begin
        shift_reg <= {shift_reg[14:0], ldsrc};
        crc_reg <= crc_reg ^ shift_reg;
        crc_count <= crc_count + 1;
        if (crc_count == 4'hF) begin
            crc_reg <= crc_reg ^ crc_expected;
            crc_count <= 4'h0;
        end
    end
end

assign regout = crc_reg;

endmodule

module up_down_counter(
    input clk,
    input rst_n,
    input enable,
    input direction,
    output reg [3:0] count
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        count <= 0;
    else if (enable) begin
        if (direction)
            count <= count + 1;
        else
            count <= count - 1;
    end
end

endmodule

