module top_module (
  input in,
  input [2:0] state,
  output reg [2:0] next_state,
  output reg out);parameter P=0, Q=1, R=2, S=3, T=4;

    always_comb begin
		case (state)
			P: next_state = in ? R : Q;
			Q: next_state = in ? S : P;
			R: next_state = in ? Q : T;
			S: next_state = in ? P : R;
			T: next_state = in ? T : S;
		endcase
    end

	assign out = (state==P) || (state==R) || (state==T);

endmodule

